      <div class="p-6 animate-in slide-in-from-left-10 duration-500 app-main-content-safe">
        <h2 class="text-2xl font-black italic uppercase mb-8 px-2">Einstellungen</h2>
        <div class="space-y-3 mb-8">
          ${[{id:"account",label:"Account",icon:"user",desc:"Profil bearbeiten"},{id:"privacy",label:"Privatsphaere",icon:"lock",desc:"Sicherheit"},{id:"notifs",label:"Benachrichtigungen",icon:"bell",desc:"Push & Email"},{id:"saved",label:"Gespeichert",icon:"bookmark",desc:"Favoriten"}].map(b=>`
            <button data-settings="${b.id}" class="w-full flex items-center justify-between p-5 bg-white rounded-[2.5rem] border border-slate-50 hover:bg-slate-50 transition-all">
              <div class="flex items-center gap-4">
                <div class="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-500">${s(b.icon,"w-4 h-4")}</div>
                <div class="text-left">
                  <span class="font-black text-slate-800 text-sm block">${b.label}</span>
                  <span class="text-[10px] font-bold text-slate-400 uppercase">${b.desc}</span>
                </div>
              </div>
              ${s("chevron-right","w-4 h-4 text-slate-300")}
            </button>
          `).join("")}
        </div>
        <button id="settingsLogout" class="w-full p-5 bg-rose-50 text-rose-500 rounded-[2.5rem] font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2">${s("log-out","w-4 h-4")} Abmelden</button>
      </div>
